def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k + k * (k - 1)
    if n == 3:
        return k * k * k + k * (k - 1) * (k - 1) + k * (k - 1) * (k - 1)
    # dp[i][j] represents the number of ways to paint i posts with j colors
    dp = [[0 for _ in range(k)] for _ in range(n + 1)]
    dp[1] = [k]
    dp[2] = [k * k + k * (k - 1)]
    dp[3] = [k * k * k + k * (k - 1) * (k - 1) + k * (k - 1) * (k - 1)]
    for i in range(4, n + 1):
        dp[i] = [dp[i - 1][0] * (k - 1) + dp[i - 2][0] * (k - 1) + dp[i - 3][0] * (k - 1)]
    return dp[n][0]

